head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setCellImageSrc]<br/>Body Cell 정보를 사용하여 특정 Body Cell 의 imageSrc 속성값을 설정합니다.",
    "validation" : [
        "Column 의 inputType='textImage' 인 경우에만 동작해야 합니다.",
        "rowIndex(필수) 파라미터로 imageSrc 속성을 설정할 Body Cell 의 Row 인덱스를 설정할 수 있어야 합니다.",
        "Row 인덱스는 0 부터 시작하며 GridView 에 표시된 Row 를 기준으로 인덱스가 설정되어야 합니다.",
        "columnInfo(필수) 파라미터로 imageSrc 속성을 설정할 Body Cell 의 Column 인덱스를 설정할 수 있어야 합니다.",
        "Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정되어야 합니다.",
        "imageSrc(선택) 파라미터로 Body Cell 에 적용할 이미지의 경로를 문자열로 설정할 수 있어야 합니다.",
        "imageSrc(선택) 파라미터에 상대경로, 절대경로, 프로토콜 포함 경로를 설정할 수 있어야 합니다.",
        "imageSrc(선택) 파라미터에 PNG, JPG, JPEG, GIF, SVG 등 웹브라우저가 지원하는 모든 이미지 파일을 설정할 수 있어야 합니다.",
        "imageSrc(선택) 파라미터에 ''(Empty String) 설정 시 해당 Body Cell 에 이미지가 표시되지 않아야 합니다.",
        "파라미터에 해당하는 Body Cell 의 imageSrc 속성값 설정 여부를 true/false 로 반환해야 합니다.",
        "파라미터가 유효하지 않거나 Column 의 inputType 속성값이 'textImage' 가 아니면 false 를 반환해야 합니다.",
        "Body Cell 의 imageSrc 속성이 설정되면 Column 의 imageSrc 속성은 무시되어야 합니다.",
        "Column 의 inputType='custom' 이고, Body Cell 의 inputType='textImage' 인 경우라도 setCellImageSrc() 메소드는 실행되지 않아야 합니다.",
        "setCellImageSrc() 메소드는 바인딩된 DataCollection 의 데이터와 Row 상태값을 변경하지 않아야 합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 파라미터 기본 선택값 설정 (정적 select1 은 초기 selectedIndex 미적용)
    par_rowIndex.setSelectedIndex(0);
    par_columnInfo.setSelectedIndex(2);
    par_imageSrc.setSelectedIndex(0);

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - Column 구성(정의 인덱스) : 0 name(text) / 1 hid(textImage, 숨김) / 2 timg(textImage, Column imageSrc 설정) / 3 cus(custom)
//    · 인덱스 1 을 setColumnVisible(1, false) 로 숨김 → 숨겨진 Column 도 인덱스에 포함되므로
//      화면상 두번째로 보이는 timg 의 Column 인덱스는 2 가 됨
//    · 0 name : inputType 이 textImage 가 아니므로 false 반환 확인용
//    · 3 cus  : Column inputType='custom' + Body Cell inputType 만 textImage 로 설정 → @spec2 미실행 확인용
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Column 구성(인덱스) : 0 = name(text) / 1 = hid(textImage, setColumnVisible 로 숨김) / 2 = timg(textImage, Column imageSrc = ico_grid_del.svg) / 3 = cus(custom, Body Cell 의 inputType 만 textImage 로 설정)\n[절차] rowIndex / columnInfo / imageSrc 를 선택하고 setCellImageSrc 버튼을 클릭하세요.\n[확인] 결과창의 반환값 / getCellImageSrc / Cell 이미지 경로 와 그리드 화면의 아이콘 표시를 비교하세요. rowIndex = 99 와 columnInfo = 99 는 유효하지 않은 파라미터 확인용입니다."', '', 'label1');

    // === 바인딩 DataList(dlt_bind) ===
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="hid" name="hid" dataType="text"></w2:column>';
    strDlt += '<w2:column id="timg" name="timg" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cus" name="cus" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "name": "John", "hid": "H0", "timg": "수정", "cus": "1" },
        { "name": "Jane", "hid": "H1", "timg": "수정", "cus": "0" },
        { "name": "Mike", "hid": "H2", "timg": "수정", "cus": "1" },
        { "name": "Amy",  "hid": "H3", "timg": "수정", "cus": "0" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // target 그리드 직접 구성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:620px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setCellImageSrc test grid"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol1" value="name (0, text)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="hid (1, 숨김)"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" id="hcol3" value="timg (2, textImage)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="cus (3, custom)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="textImage" viewType="icon" id="hid" dataList="hid"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="textImage" viewType="icon" imageSrc="/cm/images/base/ico_grid_del.svg" id="timg" dataList="timg"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="custom" id="cus" dataList="cus" trueValue="1" falseValue="0"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 인덱스 1 (hid) 숨김 → 숨겨진 Column 도 인덱스에 포함됨을 검증
    target1.setColumnVisible(1, false);

    // @spec2 : Column inputType='custom' 인 Column 의 Body Cell inputType 만 textImage 로 설정
    for (let i = 0; i < 4; i++) {
        target1.setCellInputType(i, "cus", { "inputType" : "textImage" });
    }
}



// Cell 에 실제 표시된 이미지 경로 확인
scwin.getCellImgSrc = function (rowIndex, colIndex) {
    let cellEl = document.querySelector("td[id*='target1_cell_" + rowIndex + "_" + colIndex + "']");
    if (!cellEl) {
        return "(Cell 없음)";
    }
    let imgEl = cellEl.querySelector("img");
    if (!imgEl || !imgEl.getAttribute("src")) {
        return "(이미지 미표시)";
    }
    return imgEl.getAttribute("src");
}



scwin.btn_setCellImageSrc_onclick = function () {
    let rowIndex = Number(par_rowIndex.getText());
    let columnInfo = Number(par_columnInfo.getText());
    let imageSrcText = par_imageSrc.getText();

    // 호출 전 데이터 / Row 상태값 (@spec3)
    let beforeData = JSON.stringify(dlt_bind.getAllJSON());
    let beforeStatus = dlt_bind.getRowStatus(rowIndex);

    let imageSrc;
    if (imageSrcText === "(Empty String)") {
        imageSrc = "";
    } else if (imageSrcText === "(프로토콜 포함 경로)") {
        imageSrc = location.origin + "/cm/images/base/ico_fav_on.svg";
    } else {
        imageSrc = imageSrcText;
    }
    let rtn = target1.setCellImageSrc(rowIndex, columnInfo, imageSrc);
    let paramDesc = "'" + imageSrc + "'";

    wf_body_bottom.getObj("scwin").setReturnValue("setCellImageSrc(" + rowIndex + ", " + columnInfo + ", " + paramDesc + ") : " + rtn);
    wf_body_bottom.getObj("scwin").setReturnValue("getCellImageSrc(" + rowIndex + ", " + columnInfo + ") : " + target1.getCellImageSrc(rowIndex, columnInfo));
    wf_body_bottom.getObj("scwin").setReturnValue("Cell 이미지 경로 : " + scwin.getCellImgSrc(rowIndex, columnInfo));

    // 호출 후 데이터 / Row 상태값 비교 (@spec3)
    let afterData = JSON.stringify(dlt_bind.getAllJSON());
    let afterStatus = dlt_bind.getRowStatus(rowIndex);
    wf_body_bottom.getObj("scwin").setReturnValue("데이터/Row 상태값 미변경 여부 : " + ((beforeData === afterData) && (beforeStatus === afterStatus)));
}
